package nl.slimov.app;
import android.content.Context;import org.json.*;
/** Bounded local record of received public trip observations, not a national archive. */
public final class HistoryStore {
 private static JSONArray cache;
 private static JSONArray data(Context c){if(cache==null)try{cache=new JSONArray(c.getSharedPreferences("history",0).getString("trips","[]"));}catch(Exception e){cache=new JSONArray();}return cache;}
 private static JSONObject entry(Context c,String id)throws Exception{JSONArray all=data(c);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("id").equals(id))return all.getJSONObject(i);JSONObject item=new JSONObject().put("id",id).put("gps",new JSONObject()).put("at",System.currentTimeMillis());JSONArray next=new JSONArray().put(item);for(int i=0;i<Math.min(11,all.length());i++)next.put(all.get(i));cache=next;return item;}
 private static void save(Context c){c.getSharedPreferences("history",0).edit().putString("trips",cache.toString()).putLong("version",System.currentTimeMillis()).apply();}
 public static synchronized void remember(Context c,JSONObject trip,String id)throws Exception{JSONArray legs=trip.optJSONArray("legs"),selected=new JSONArray();if(legs==null)return;for(int i=0;i<legs.length();i++)if(legs.getJSONObject(i).optString("tripId").equals(id))selected.put(legs.get(i));if(selected.length()==0)return;entry(c,id).put("trip",new JSONObject().put("legs",selected)).put("at",System.currentTimeMillis());save(c);}
 public static synchronized void gps(Context c,JSONObject reminder,JSONObject progress,JSONObject vehicle)throws Exception{String id=reminder.optString("tripId");if(id.isEmpty()||!progress.optBoolean("reliable"))return;JSONObject item=entry(c,id),events=item.getJSONObject("gps");JSONArray stops=reminder.getJSONObject("model").getJSONArray("stops");boolean changed=false;int passed=progress.optInt("passed",-1),current=progress.optInt("current",-1);for(int i=0;i<stops.length();i++){if(i>passed)break;JSONObject s=stops.getJSONObject(i);String key=String.valueOf(i+1);boolean stopped=current==i&&(vehicle.optInt("stopStatus",-1)==1&&vehicle.optString("stop").replaceFirst("^nl-OpenOV_","").equals(s.optString("id"))||vehicle.optString("event").equals("ONSTOP")&&!s.optString("stopCode").isEmpty()&&s.optString("stopCode").equals(vehicle.optString("userstopcode")));if(!events.has(key)||stopped&&!events.getJSONObject(key).optBoolean("confirmed")){JSONObject e=new JSONObject().put("ordinal",i+1).put("id",s.optString("id")).put("name",s.optString("name")).put("confirmed",stopped).put("kind",stopped?"stop-observation":"gps-passed").put("source",stopped?"Eerste ontvangen stilstandmeting; geen officiële aankomsttijd":"Gepasseerd volgens GPS; geen exact haltetijdstip");String time=java.time.Instant.ofEpochSecond(vehicle.optLong("timestamp")).toString();if(stopped)e.put("actual",time);else e.put("windowEnd",time);if(vehicle.has("delay"))e.put("delay",vehicle.optDouble("delay"));events.put(key,e);changed=true;}}if(changed){item.put("at",System.currentTimeMillis());save(c);}}
}
